    <style nonce="M8z9jOr-GIpv_vp9mx0Yvg">
        html {
            overflow: hidden;
        }

        body {
            font: 12px Roboto, Arial, sans-serif;
            background-color: #000;
            color: #fff;
            height: 100%;
            width: 100%;
            overflow: hidden;
            position: absolute;
            margin: 0;
            padding: 0;
        }

        #player {
            width: 100%;
            height: 100%;
        }

        h1 {
            text-align: center;
            color: #fff;
        }

        h3 {
            margin-top: 6px;
            margin-bottom: 3px;
        }

        .player-unavailable {
            position: absolute;
            top: 0;
            left: 0;
            right: 0;
            bottom: 0;
            padding: 25px;
            font-size: 13px;
            background: url(/img/meh7.png) 50% 65% no-repeat;
        }

        .player-unavailable .message {
            text-align: left;
            margin: 0 -5px 15px;
            padding: 0 5px 14px;
            border-bottom: 1px solid #888;
            font-size: 19px;
            font-weight: normal;
        }

        .player-unavailable a {
            color: #167ac6;
            text-decoration: none;
        }
    </style>
